-- FUNCTION: cjams.personsearch_global_nosort(json)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       

 DROP FUNCTION IF EXISTS cjams.personsearch_global_nosort(json);

CREATE OR REPLACE FUNCTION cjams.personsearch_global_nosort(searchobj json)
 RETURNS TABLE(totalcount bigint, exactmatch boolean, rankno integer, source character varying, personid uuid, personroleid uuid, personroletype character varying, personrolesubtype character varying, firstname character varying, middlename character varying, lastname character varying, dob timestamp without time zone, dangerlevel integer, dateofdeath timestamp without time zone, isapproxdod integer, suffix character varying, prefx character varying, deceased bit, socialmediasource character varying, userphoto text, ssn character varying, mdm_id character varying, dcn character varying, dl character varying, primaryaddress character varying, address character varying, address2 character varying, county character varying, city character varying, state character varying, zipcode character varying, homephone character varying, gendertypekey character varying, loadnumber character varying, teamname character varying, priors bigint, relationscount bigint, relations text, alias text, assistpid character varying, cjamspid character varying, primarylanguageid character varying, secondarylanguageid character varying, primarylanguage character varying, secondarylanguage character varying, safehavenbabyflag integer, racetypekey text, ethnicgrouptypekey character varying, cisclientid character varying, isbioadoptedflag integer, isProvider character varying)
 LANGUAGE plpgsql
AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
 ------------------------------------------------------------------------------------------------------------
-- Revision(s)
-- 09/14/2023 Palani/Chandra - Performance tugning (CIDM-7932)
-- 01/18/2024 Palani/Manasa - Performance tugning (CIDM-8343)
-- 03/14/2025 Manasa Kasula - Person search Enhancements (CIDM-10291)
------------------------------------------------------------------------------------------------------------                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
 DECLARE
  --v_ldNow        TIMESTAMP(3); -- Not used 6/24/2019
 v_liPageNumber    INT;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
