 v_lvFirstName    VARCHAR(50);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
 v_lvLastName      VARCHAR(50);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
 v_lvMiddleName    VARCHAR(50);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
 v_liAge        INT;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
 v_lvRace        VARCHAR(15);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
 v_lvGender      VARCHAR(15);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
 v_lvCity        VARCHAR(32);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
 v_lvAddress      VARCHAR(100); 
 v_lvAddress2   VARCHAR(100);
 v_lvZip        VARCHAR(32);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
 v_lvState      VARCHAR(32);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
 v_lvCounty      VARCHAR(50);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
 v_lvPhone      VARCHAR(32);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
 --v_ldDOB        TIMESTAMP(3);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
 v_ldDOB        varchar(50);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
 v_liActiveFlag    INT;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
 v_lvRoleType      VARCHAR(10);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
 --v_lvRoleSubType    TEXT;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
 v_liCount      INT;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
-- v_lvSortCol      VARCHAR(50);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
-- v_lvSortDir      VARCHAR(10);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
 v_lvInterfaceType  VARCHAR(20);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
 v_liCommaPos      INT;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
 v_liPersonFlag        CHAR(1);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
 v_liDangerous          INT;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
 v_liRegion      INT;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
 v_ldDOBFrom      TIMESTAMP(3);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
 v_ldDOBTo      TIMESTAMP(3);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
 v_lSSNType  VARCHAR(50);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
 v_lSSNValue  VARCHAR(50);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
 v_lDCNType  VARCHAR(50);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
 v_lDCNValue  VARCHAR(50);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
 v_lDLType  VARCHAR(50);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
 v_lDLValue  VARCHAR(50);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
 v_lvMaidenName  VARCHAR(50);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
 v_lvSocialMediaSrc  VARCHAR(250);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
 v_lvStateId  VARCHAR(150);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
 v_lvDateOfDeath  TIMESTAMP(3);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
 v_lvOccupation  VARCHAR(150);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
 v_lvFein  VARCHAR(50);
 v_lvComplaintnumber  VARCHAR(50);
 v_lvCjisnumber_spaced VARCHAR(50);
 v_lvCjisnumber  VARCHAR(50);
 v_lvcjamspid  VARCHAR(50);
 v_lvPetitionid  VARCHAR(50);

 v_lvAlias  VARCHAR(50);
 v_lvEmail  VARCHAR(50);

 v_pageoffset  int;
 v_pagenumber  int;
 cnt  int;
 -- rec  record;
 v_assistpid  VARCHAR(50);  -- not currently used
 v_cjamspid  VARCHAR(50);   -- not currently used
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
 v_krcount int;
 sortcolumn VARCHAR(50);
 sortorder VARCHAR(50);
 v_sort_order_string character varying;
 v_lmdmType  VARCHAR(50);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
 v_lmdmValue  VARCHAR(50); 

  v_firstname_clean varchar(50);
  v_lastname_clean varchar(50);
  v_middlename_clean varchar(50);
  v_maidenname_clean varchar(50);
  v_alias_clean varchar(50);
  
  soundex_firstname varchar(50);
  soundex_lastname varchar(50);
  soundex_middlename varchar(50);
 
  searchargperson int;
  searchargcount int;
  args varchar;
  soundslikeindex int;
  argcount int;
  personid_list uuid[];
  
  v_dob_from  date;
  v_dob_to 	date;

 BEGIN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
 CREATE  TEMP  TABLE  sp_temp_searchParms(parmKeyword  VARCHAR(50), parmValue  VARCHAR(1000), isPerson boolean default false);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
 CREATE  TEMP  TABLE  sp_temp_PersonIdentityTypes  (parmValue  VARCHAR(50));                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
 CREATE  TEMP  TABLE  sp_temp_PersonIdentityValues  (paramtype  varchar(50),parmValue  VARCHAR(50));                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
 v_liPageNumber  :=  searchObj  ->>  'pagenumber'  ;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
 v_liPageSize  :=  searchObj  ->>  'pagesize'  ;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
 v_lvFirstName  :=  searchObj  ->>  'firstname';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
 v_lvLastName  :=  searchObj  ->>  'lastname';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
 v_lvMiddleName  :=  searchObj  ->>  'middlename';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
 v_liAge  :=  searchObj  ->>  'age';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
 v_lvRace  :=  searchObj  ->>  'race';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
 v_lvGender  :=  searchObj  ->>  'gender';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
 v_lvCity  :=  searchObj  ->>  'city';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
 v_lvAddress  :=  searchObj  ->>  'address1'; 
 v_lvAddress2  :=  searchObj  ->>  'address2'; 
 v_lvZip  :=  searchObj  ->>  'zip';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
 v_lvState  :=  searchObj  ->>  'state';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
 v_lvCounty  :=  searchObj  ->>  'county';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
 v_lvPhone  :=  searchObj  ->>  'phone';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
 v_ldDOB  :=  searchObj  ->>  'dob'  ;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
 v_liActiveFlag  :=  searchObj  ->>  'activeflag';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
 v_lvRoleType  :=  searchObj  ->>  'roletype'; 
 v_lvInterfaceType  :=  searchObj  ->>  'interfacetype';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
 v_liPersonFlag  :=  searchObj  ->>  'personflag';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
 v_liDangerous  :=  searchObj  ->>  'dangerous';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
 v_liRegion  :=  searchObj  ->>  'region';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
 v_ldDOBFrom  :=  searchObj  ->>  'dobfrom';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
 v_ldDOBTo  :=  searchObj  ->>  'dobto';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
 v_lvMaidenName  :=  searchObj  ->>  'maidenname';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
 v_lvSocialMediaSrc  :=  searchObj  ->>  'mediasrc';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
 v_lvStateId  :=  searchObj  ->>  'stateid';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
 v_lvDateOfDeath  :=  searchObj  ->>  'dateofdeath';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
 v_lvOccupation  :=  searchObj  ->>  'occupation';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
 v_lvFein  :=  searchObj  ->>  'fein';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
 v_lvComplaintnumber  :=  searchObj  ->>  'complaintnumber';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
 v_lvCjisnumber_spaced  :=  searchObj  ->>  'cjisnumber';
 v_lvcjamspid := searchObj  ->>  'cjamspid';
 v_lvPetitionid  :=  searchObj  ->>  'petitionid';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
 v_lvAlias  :=  searchObj  ->>  'alias';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
 v_lvEmail  :=  searchObj  ->>  'email';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
 v_assistpid  :=  searchObj  ->>  'assistpid';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
 v_cjamspid  :=  searchObj  ->>  'cjamspid';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
 v_pagenumber  :=  v_liPageNumber-1;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
 v_pageoffset  =  (v_pagenumber  *  v_liPageSize);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
 v_lvAddress  :=  replace(v_lvAddress,  '  ',  '%');    
 v_lvAddress2  :=  replace(v_lvAddress2,  '  ',  '%');
 sortcolumn  :=  searchObj  ->>  'sortcolumn';
 sortorder  :=  searchObj  ->>  'sortorder';
 v_lvCjisnumber  := trim(v_lvCjisnumber_spaced);
  v_firstname_clean  := trim(lower(v_lvFirstName));
  v_lastname_clean   := trim(lower(v_lvLastName));
  v_middlename_clean := trim(lower(v_lvMiddleName));
  v_maidenname_clean := trim(lower(v_lvMaidenName));
  v_alias_clean      := trim(lower(v_lvAlias));
  soundslikeindex := 3; --used to control difference() matching
  soundex_firstname := soundex(v_firstname_clean);
  soundex_lastname := soundex(v_lastname_clean);
  soundex_middlename := soundex(v_middlename_clean);  
 INSERT  INTO  sp_temp_searchParms(  parmKeyword,  parmValue)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
     values
     ('age',searchObj  ->>  'age'),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
     ('race',searchObj  ->>  'race'),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
     ('gender',searchObj  ->>  'gender'),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
     ('city',searchObj  ->>  'city'),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
     ('address',searchObj  ->>  'address1'),
     ('address2',searchObj  ->>  'address2'),
     ('zip',searchObj  ->>  'zip'),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
     ('state',searchObj  ->>  'state'),
     ('stateid',searchObj  ->>  'stateid'),
     ('county',searchObj  ->>  'county'),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
     ('phone',searchObj  ->>  'phone'),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
     ('dob',searchObj  ->>  'dob'),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
     ('activeflag',searchObj  ->>  'activeflag'), 
     ('roletype',searchObj  ->>  'roletype'),
     ('interfacetype',searchObj  ->>  'interfacetype'),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
     ('personflag',searchObj  ->>  'personflag'),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
     ('dangerous',searchObj  ->>  'dangerous'),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
     ('region',searchObj  ->>  'region'),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
     ('dobfrom',searchObj  ->>  'dobfrom'),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
     ('dobto',searchObj  ->>  'dobto'),  
     ('DCN',searchObj  ->>  'dcn'),
     ('DL',searchObj  ->>  'dl'),
     ('SSN',searchObj  ->>  'ssn'),
     ('maidenname',searchObj  ->>  'maidenname'),
     ('mediasrc',searchObj  ->>  'mediasrc'),
     ('dateofdeath',searchObj  ->>  'dateofdeath'),
     ('occupation',searchObj  ->>  'occupation'),
     ('fein',searchObj  ->>  'fein'),
     ('complaintnumber',searchObj  ->>  'complaintnumber'),
     ('cjisnumber',searchObj  ->>  'cjisnumber'),
     ('cjamspid',searchObj  ->>  'cjamspid'),
     ('petitionid',searchObj  ->>  'petitionid'),
     ('alias',searchObj  ->>  'alias'),
     ('email',searchObj  ->>  'email'),
     ('assistpid',searchObj  ->>  'assistpid'),
     ('MDM_ID',searchObj  ->>  'mdmId');

 INSERT  INTO  sp_temp_searchParms(parmKeyword, parmValue, isPerson) 
     values  
     ('firstname', v_lvFirstName, true),
     ('lastname', v_lvLastName, true),
     ('middlename', v_lvMiddleName, true);

  select string_agg(parmKeyword,',') into args  from sp_temp_searchParms where parmValue is not null;
  select count(*) into searchargperson from sp_temp_searchParms where parmValue is not null and isPerson;
  select count(*) into searchargcount from sp_temp_searchParms where parmValue is not null ; 
  raise notice 'searchparams count % %', searchargperson, searchargcount;
 raise notice 'searchparams list %', args;
 
 IF (v_ldDOB IS NOT NULL AND length(v_ldDOB) > 4) THEN
		SELECT 	((DATE_PART('year', v_ldDOB::date) - 3)::CHARACTER VARYING ||'-01-01')::date,
				((DATE_PART('year', v_ldDOB::date) + 3)::CHARACTER VARYING ||'-12-31')::date
		 INTO   v_dob_from, v_dob_to;
		
		RAISE NOTICE 'v_ldDOB %', v_ldDOB;
		RAISE NOTICE 'v_dob_from %', v_dob_from;
		RAISE NOTICE 'v_dob_to %', v_dob_to;
 END IF; 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
 IF  (LENGTH(v_lvState)  >  2)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
	THEN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
		SELECT      ST.StateAbbr  INTO  v_lvState                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
		FROM  State    ST                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
		WHERE  ST.StateName  =    v_lvState;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
END  IF;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
 IF  (v_liActiveFlag  =  -1  OR  v_liActiveFlag  is  null)  THEN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
	v_liActiveFlag  :=  NULL;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
END  IF;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
 INSERT  INTO  sp_temp_PersonIdentityTypes                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
 SELECT  parmKeyword                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
 FROM  sp_temp_searchParms                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
 WHERE  parmKeyword  in ('DCN','DL','SSN','MDM_ID')  and  parmValue  is  not  null;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
 INSERT  INTO  sp_temp_PersonIdentityValues                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
 SELECT  parmKeyword,parmValue                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
 FROM  sp_temp_searchParms                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
 WHERE  parmKeyword  in  ('SSN','DL','DCN','MDM_ID');                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
 SELECT  PIT.parmValue  INTO  v_lSSNType                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
	FROM  sp_temp_PersonIdentityTypes    PIT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
	WHERE  PIT.parmValue  =  'SSN';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
 SELECT  PIT.parmValue  INTO  v_lDCNType                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
	FROM  sp_temp_PersonIdentityTypes    PIT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
	WHERE  PIT.parmValue  =  'DCN';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
 SELECT  PIT.parmValue  INTO  v_lDLType                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
	FROM  sp_temp_PersonIdentityTypes    PIT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
	WHERE  PIT.parmValue  =  'DL';         
 
  SELECT  PIT.parmValue  INTO  v_lmdmType                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
	FROM  sp_temp_PersonIdentityTypes    PIT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
	WHERE  PIT.parmValue  =  'MDM_ID';   
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
 --------------------                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
SELECT  PIV.parmValue  INTO  v_lDCNValue                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
	FROM  sp_temp_PersonIdentityValues  PIV  where  PIV.paramtype  =  'DCN';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
 SELECT  PIV.parmValue  INTO  v_lSSNValue                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
	FROM  sp_temp_PersonIdentityValues  PIV  where  PIV.paramtype  =  'SSN';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
 SELECT  PIV.parmValue  INTO  v_lDLValue                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
	FROM  sp_temp_PersonIdentityValues  PIV  where  PIV.paramtype  =  'DL';    
 
SELECT  PIV.parmValue  INTO  v_lmdmValue                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
FROM  sp_temp_PersonIdentityValues  PIV  where  PIV.paramtype  =  'MDM_ID'; 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
 ---------------------                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
     RAISE  NOTICE  'eeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeee-->%','sdfsdfsd';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
     RAISE  NOTICE  '%','==========================================================';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
         RAISE  NOTICE  'v_lvLastName::  %',v_lvLastName;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
         RAISE  NOTICE  'v_lvFirstName::  %',v_lvFirstName;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
         RAISE  NOTICE  'v_lvMiddleName::  %',v_lvMiddleName;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
         RAISE  NOTICE  'v_lvRace::  %',v_lvRace;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
         RAISE  NOTICE  'v_lvGender::  %',v_lvGender;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
         RAISE  NOTICE  'v_ldDOB::  %',v_ldDOB;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
         RAISE  NOTICE  'v_ldDOBFrom::  %',v_ldDOBFrom;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
         RAISE  NOTICE  'v_ldDOBTo::  %',v_ldDOBTo;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
         RAISE  NOTICE  'v_liActiveFlag::  %',v_liActiveFlag;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
         RAISE  NOTICE  'v_lvCity::  %',v_lvCity;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
         RAISE  NOTICE  'v_lvAddress::  %',v_lvAddress;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
         RAISE  NOTICE  'v_lvZip::  %',v_lvZip;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
         RAISE  NOTICE  'v_lvState::  %',v_lvState;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
         RAISE  NOTICE  'v_lvCounty::  %',v_lvCounty;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
         RAISE  NOTICE  'v_lvPhone::  %',v_lvPhone;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
         RAISE  NOTICE  'v_lDCNValue::  %',v_lDCNValue;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
         RAISE  NOTICE  'v_lDCNType::  %',v_lDCNType;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
         RAISE  NOTICE  'v_lDLValue::  %',v_lDLValue;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
         RAISE  NOTICE  'v_lDLType::  %',v_lDLType;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
         RAISE  NOTICE  'v_lSSNValue::  %',v_lSSNValue;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
         RAISE  NOTICE  'v_lSSNType::  %',v_lSSNType;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
         RAISE  NOTICE  'v_liDangerous::  %',v_liDangerous;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
         RAISE  NOTICE  'v_liRegion::  %',v_liRegion;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
     RAISE  NOTICE  '%','==========================================================';   

  CREATE TEMP TABLE KeyResults(PersonId uuid, PersonAddressId uuid, RankNo int, RankSound int, MatchScore int, NameRank int, AliasRank int);
  argcount := 1;
  IF (v_lSSNValue IS NOT NULL) THEN
		argcount := argcount + 1;
		INSERT INTO KeyResults (PersonId, RankNo, MatchScore, NameRank, AliasRank)
			SELECT 
				distinct
				p.PersonId,
				99 as match_rank,
				searchargperson as match_score,
				0 as name_rank,
				0 as alias_rank
			FROM    Person  AS  p                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
			LEFT  JOIN  PersonIdentifier  AS  i  ON  i.PersonId  =  p.PersonId
			LEFT  JOIN  PersonAddress    AS  a  ON  a.PersonId  =  p.PersonId  and  a.ActiveFlag  =  1  --AND  a.PersonAddressTypeKey  =  'C'
			LEFT  JOIN  PersonPhoneNumber  AS  pn  ON  pn.PersonId  =  p.PersonId
			LEFT  JOIN  PersonEmail  AS  pe  ON  pe.PersonId  =  p.PersonId
			LEFT  JOIN  County        AS  c  ON    a.county :: character varying  =  c.countyid :: character varying
			Left  Join  Alias  As  al  On  al.personid  =  p.personid
			WHERE (p.clientflag is null or p.clientflag in (1,2) or p.cisclientid is not null)
			AND  i.PersonIdentifierValue = v_lSSNValue
			AND p.ActiveFlag  =  1;		
  END IF;

  IF (v_lvCjisnumber IS NOT NULL) THEN
		argcount := argcount + 1;
		INSERT INTO KeyResults (PersonId, RankNo, MatchScore, NameRank, AliasRank)
			SELECT 
				distinct
				p.PersonId,
				99 as match_rank,
				searchargperson as match_score,
				0 as name_rank,
				0 as alias_rank
			FROM    Person  AS  p                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
			LEFT  JOIN  PersonIdentifier  AS  i  ON  i.PersonId  =  p.PersonId
			LEFT  JOIN  PersonAddress    AS  a  ON  a.PersonId  =  p.PersonId  and  a.ActiveFlag  =  1  --AND  a.PersonAddressTypeKey  =  'C'
			LEFT  JOIN  PersonPhoneNumber  AS  pn  ON  pn.PersonId  =  p.PersonId
			LEFT  JOIN  PersonEmail  AS  pe  ON  pe.PersonId  =  p.PersonId
			LEFT  JOIN  County        AS  c  ON    a.county :: character varying  =  c.countyid :: character varying
			Left  Join  Alias  As  al  On  al.personid  =  p.personid
			WHERE (p.clientflag is null or p.clientflag in (1,2) or p.cisclientid is not null)
				AND (i.PersonIdentifierValue = v_lvCjisnumber) AND p.ActiveFlag  =  1
			union
				SELECT 
				distinct
				p.PersonId,
				99 as match_rank,
				searchargperson as match_score,
				0 as name_rank,
				0 as alias_rank
			FROM    Person  AS  p                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
			LEFT  JOIN  PersonIdentifier  AS  i  ON  i.PersonId  =  p.PersonId
			LEFT  JOIN  PersonAddress    AS  a  ON  a.PersonId  =  p.PersonId  and  a.ActiveFlag  =  1  --AND  a.PersonAddressTypeKey  =  'C'
			LEFT  JOIN  PersonPhoneNumber  AS  pn  ON  pn.PersonId  =  p.PersonId
			LEFT  JOIN  PersonEmail  AS  pe  ON  pe.PersonId  =  p.PersonId
			LEFT  JOIN  County        AS  c  ON    a.county :: character varying  =  c.countyid :: character varying
			Left  Join  Alias  As  al  On  al.personid  =  p.personid
			WHERE (p.clientflag is null or p.clientflag in (1,2) or p.cisclientid is not null)
				AND (trim(p.cisclientid) = v_lvCjisnumber::character varying) AND p.ActiveFlag  =  1;
  END IF;
  
  IF (argcount > 1 and v_lvCjisnumber IS NULL) THEN
	SELECT array_agg(k.personid) into personid_list from KeyResults k ;
  END IF;

	IF (searchargcount > argcount) THEN

		IF (v_lvFirstName IS NOT NULL OR v_lvLastName IS NOT NULL OR v_lvMiddleName IS NOT NULL) THEN
			
			INSERT INTO KeyResults
			(PersonId, RankNo, MatchScore,NameRank, AliasRank)
		
			SELECT 
				distinct
				p.PersonId,
				0 AS match_rank,
				CASE 	WHEN v_lvFirstName is not null and coalesce(v_firstname_clean,' ') = trim(lower(p.FirstName)) THEN 1 
						WHEN v_lvFirstName is not null and coalesce(v_firstname_clean,' ') = trim(lower(al.FirstName)) THEN 1 
						WHEN v_lvFirstName is not null and trim(lower(p.FirstName)) like v_firstname_clean||'%' THEN 1 
						WHEN v_lvFirstName is not null and trim(lower(al.FirstName)) like v_firstname_clean||'%' THEN 1 
						WHEN v_lvFirstName is not null and coalesce(v_firstname_clean,' ') = split_part(trim(lower(p.FirstName)), ' ',1) THEN 1 
						WHEN v_lvFirstName is not null and coalesce(v_firstname_clean,' ') = split_part(trim(lower(al.FirstName)), ' ',1) THEN 1 
						ELSE 0 end
				+ CASE 	WHEN v_lvLastName is not null and coalesce(v_lastname_clean,' ') = trim(lower(p.LastName)) THEN 1 
						WHEN v_lvLastName is not null and coalesce(v_lastname_clean,' ') = trim(lower(al.LastName)) THEN 1 
						WHEN v_lvLastName is not null and trim(lower(p.LastName)) like v_lastname_clean||'%' THEN 1
						WHEN v_lvLastName is not null and trim(lower(al.LastName)) like v_lastname_clean||'%' THEN 1
						WHEN v_lvLastName is not null and coalesce(v_lastname_clean,' ') = split_part(trim(lower(p.LastName)), ' ',1) THEN 1 
						WHEN v_lvLastName is not null and coalesce(v_lastname_clean,' ') = split_part(trim(lower(al.LastName)), ' ',1) THEN 1 
						ELSE 0 end
				+ CASE WHEN v_lvMiddleName is not null and coalesce(v_middlename_clean,' ') = trim(lower(p.MiddleName)) THEN 1 
				WHEN v_lvMiddleName is not null and coalesce(v_middlename_clean,' ') = split_part(trim(lower(p.MiddleName)), ' ',2) THEN 1 ELSE 0 end
				::int as match_score,
				CASE 	WHEN v_lvFirstName is not null THEN COALESCE(difference(v_firstname_clean, trim(lower(p.FirstName))),0) ELSE 0 end
				+ CASE 	WHEN v_lvLastName is not null THEN COALESCE(difference(v_lastname_clean, trim(lower(p.LastName))),0) ELSE 0 end
				+ CASE 	WHEN v_lvMiddleName is not null THEN COALESCE(difference(v_middlename_clean, trim(lower(p.MiddleName))),0) ELSE 0 end
				::int as name_rank,
				CASE 	WHEN v_lvFirstName is not null THEN COALESCE(difference(v_firstname_clean, trim(lower(al.FirstName))),0) ELSE 0 end
				+ CASE 	WHEN v_lvLastName is not null THEN COALESCE(difference(v_lastname_clean, trim(lower(al.LastName))),0) ELSE 0 end
				+ CASE 	WHEN v_lvMiddleName is not null THEN COALESCE(difference(v_middlename_clean, trim(lower(al.MiddleName))),0) ELSE 0 end
				::int as alias_rank
			FROM    Person  AS  p  
			LEFT  JOIN  PersonIdentifier  AS  i  ON  i.PersonId  =  p.PersonId 
			LEFT  JOIN  PersonAddress    AS  a  ON  a.PersonId  =  p.PersonId  and  a.ActiveFlag  =  1
			LEFT  JOIN  PersonPhoneNumber  AS  pn  ON  pn.PersonId  =  p.PersonId
			LEFT  JOIN  PersonEmail  AS  pe  ON  pe.PersonId  =  p.PersonId
			LEFT  JOIN  County        AS  c  ON    a.county :: character varying  =  c.countyid :: character varying
			Left  Join  Alias  As  al  On  al.personid  =  p.personid
			WHERE (p.clientflag is null or p.clientflag in (1,2) or p.cisclientid is not null)
			AND CASE WHEN personid_list IS NOT NULL THEN p.personid != ANY (personid_list::uuid[]) ELSE TRUE END
			AND CASE WHEN v_lvFirstName  is NOT NULL THEN soundex_firstname = soundex(lower(trim(p.FirstName)))  ELSE TRUE END
			AND CASE WHEN v_lvLastName 	 is NOT NULL THEN soundex_lastname = soundex(lower(trim(p.LastName)))	 ELSE TRUE END
			AND CASE WHEN v_lvMiddleName is NOT NULL THEN soundex_middlename = soundex(lower(trim(p.MiddleName))) ELSE TRUE END
			AND CASE WHEN v_lvRace is NOT NULL THEN (p.RaceTypeKey = v_lvRace) ELSE TRUE END
			AND CASE WHEN v_lvGender is NOT NULL THEN (p.GenderTypeKey = v_lvGender) ELSE TRUE END
			AND CASE WHEN v_lDCNType is NOT NULL THEN (i.PersonIdentifierTypeKey = v_lDCNType) ELSE TRUE END
			AND CASE WHEN v_liDangerous is NOT NULL THEN (p.DangerLevel = v_liDangerous) ELSE TRUE END
			AND CASE WHEN v_liRegion is NOT NULL THEN (c.APSRegion = v_liRegion) ELSE TRUE END
			AND (CASE WHEN (v_lDLType is NOT NULL AND v_lDLValue is NOT NULL)
						THEN (i.PersonIdentifierTypeKey = v_lDLType AND i.PersonIdentifierValue ILIKE v_lDLValue)
					ELSE TRUE END)
			and CASE WHEN v_lvStateId is NOT NULL THEN a.state ILIKE v_lvStateId ELSE TRUE end
			AND CASE WHEN  v_lvAddress  is  NOT  NULL  THEN  (lower(a.address)  ILIKE  lower(v_lvAddress)||'%' )  ELSE  TRUE  end
			AND CASE WHEN  v_lvAddress2  is  NOT  NULL  THEN  (lower(a.address2) ILIKE  lower(v_lvAddress2)||'%' )  ELSE  TRUE  END
			AND CASE WHEN v_lvSocialMediaSrc is NOT NULL THEN (lower(p.socialmediasource) = lower(v_lvSocialMediaSrc)) ELSE TRUE END
			AND CASE WHEN v_lvFein is NOT NULL THEN (p.fein = v_lvFein) ELSE TRUE END
			AND CASE WHEN v_lvComplaintnumber is NOT NULL THEN (p.complaintnumber = v_lvComplaintnumber) ELSE TRUE end
			AND CASE WHEN v_lvcjamspid is NOT NULL THEN ( p.cjamspid = v_lvcjamspid::bigint) ELSE TRUE END
			AND CASE WHEN v_lvPetitionid is NOT NULL THEN (p.petitionid = v_lvPetitionid) ELSE TRUE END
			AND 
				CASE 
					WHEN v_lvAlias is NOT NULL 
					THEN ((concat(trim(lower(al.firstname)), case when al.lastname is not null then '' else ' '|| trim(lower(al.lastname)) end ) = v_alias_clean) and al.akatypetypekey='AN' and al.activeflag=1)
					ELSE true
				END
			AND CASE 
					WHEN v_lvMaidenName is NOT NULL 
					THEN ((concat(lower(al.firstname), case when al.lastname is not null then '' else ' '|| lower(al.lastname) end ) = v_maidenname_clean) and al.akatypetypekey='MN' and al.activeflag=1)
					ELSE true
				END
			AND CASE WHEN v_lvZip is NOT NULL THEN (lower(a.zipcode) = lower(v_lvZip)) ELSE TRUE END
			AND CASE WHEN v_lvState is NOT NULL THEN (a.state ILIKE v_lvState) ELSE TRUE END
			AND CASE WHEN v_lvCounty is NOT NULL THEN (a.county ILIKE v_lvCounty) ELSE TRUE END
			AND CASE WHEN v_lvCity is NOT NULL THEN (lower(a.city) = lower(v_lvCity)) ELSE TRUE END
			AND CASE WHEN v_lDCNValue is NOT NULL THEN (i.PersonIdentifierValue ILIKE v_lDCNValue) ELSE TRUE END
			AND CASE WHEN v_lvPhone is NOT NULL THEN (pn.phoneNumber ILIKE v_lvPhone) ELSE TRUE END
			AND CASE WHEN v_lvEmail is NOT NULL THEN (pe.email ILIKE v_lvEmail) ELSE TRUE END
			AND CASE WHEN v_lvOccupation is NOT NULL THEN (p.occupation ILIKE v_lvOccupation) ELSE TRUE END
			AND (v_liAge IS NULL OR date_part('year', age(now(), p.DOB)) = v_liAge)
			AND CASE WHEN v_lmdmType is NOT NULL THEN (i.PersonIdentifierTypeKey = v_lmdmType) ELSE TRUE end
			AND CASE WHEN v_lmdmValue is NOT NULL THEN (i.PersonIdentifierValue ilike '%'  || v_lmdmValue ||  '%' ) ELSE TRUE END
			AND CASE WHEN v_ldDOB is NOT NULL THEN (p.DOB BETWEEN v_dob_from AND v_dob_to) ELSE TRUE END 
			AND p.ActiveFlag  =  1
	
			UNION
		
			SELECT 
				distinct
				p.PersonId,
				0 AS match_rank,
				CASE 	WHEN v_lvFirstName is not null and coalesce(v_firstname_clean,' ') = trim(lower(p.FirstName)) THEN 1 
						WHEN v_lvFirstName is not null and coalesce(v_firstname_clean,' ') = trim(lower(al.FirstName)) THEN 1 
						WHEN v_lvFirstName is not null and trim(lower(p.FirstName)) like v_firstname_clean||'%' THEN 1 
						WHEN v_lvFirstName is not null and trim(lower(al.FirstName)) like v_firstname_clean||'%' THEN 1 
						WHEN v_lvFirstName is not null and coalesce(v_firstname_clean,' ') = split_part(trim(lower(p.FirstName)), ' ',1) THEN 1 
						WHEN v_lvFirstName is not null and coalesce(v_firstname_clean,' ') = split_part(trim(lower(al.FirstName)), ' ',1) THEN 1 
						ELSE 0 end
				+ CASE 	WHEN v_lvLastName is not null and coalesce(v_lastname_clean,' ') = trim(lower(p.LastName)) THEN 1 
						WHEN v_lvLastName is not null and coalesce(v_lastname_clean,' ') = trim(lower(al.LastName)) THEN 1 
						WHEN v_lvLastName is not null and trim(lower(p.LastName)) like v_lastname_clean||'%' THEN 1
						WHEN v_lvLastName is not null and trim(lower(al.LastName)) like v_lastname_clean||'%' THEN 1
						WHEN v_lvLastName is not null and coalesce(v_lastname_clean,' ') = split_part(trim(lower(p.LastName)), ' ',1) THEN 1 
						WHEN v_lvLastName is not null and coalesce(v_lastname_clean,' ') = split_part(trim(lower(al.LastName)), ' ',1) THEN 1 
						ELSE 0 end
				+ CASE WHEN v_lvMiddleName is not null and coalesce(v_middlename_clean,' ') = trim(lower(p.MiddleName)) THEN 1 
				WHEN v_lvMiddleName is not null and coalesce(v_middlename_clean,' ') = split_part(trim(lower(p.MiddleName)), ' ',2) THEN 1 ELSE 0 end
				::int as match_score,
				CASE 	WHEN v_lvFirstName is not null THEN COALESCE(difference(v_firstname_clean, trim(lower(p.FirstName))),0) ELSE 0 end
				+ CASE 	WHEN v_lvLastName is not null THEN COALESCE(difference(v_lastname_clean, trim(lower(p.LastName))),0) ELSE 0 end
				+ CASE 	WHEN v_lvMiddleName is not null THEN COALESCE(difference(v_middlename_clean, trim(lower(p.MiddleName))),0) ELSE 0 end
				::int as name_rank,
				CASE 	WHEN v_lvFirstName is not null THEN COALESCE(difference(v_firstname_clean, trim(lower(al.FirstName))),0) ELSE 0 end
				+ CASE 	WHEN v_lvLastName is not null THEN COALESCE(difference(v_lastname_clean, trim(lower(al.LastName))),0) ELSE 0 end
				+ CASE 	WHEN v_lvMiddleName is not null THEN COALESCE(difference(v_middlename_clean, trim(lower(al.MiddleName))),0) ELSE 0 end
				::int as alias_rank
			FROM    Person  AS  p  
			LEFT  JOIN  PersonIdentifier  AS  i  ON  i.PersonId  =  p.PersonId 
			LEFT  JOIN  PersonAddress    AS  a  ON  a.PersonId  =  p.PersonId  and  a.ActiveFlag  =  1  --AND  a.PersonAddressTypeKey  =  'C'
			LEFT  JOIN  PersonPhoneNumber  AS  pn  ON  pn.PersonId  =  p.PersonId
			LEFT  JOIN  PersonEmail  AS  pe  ON  pe.PersonId  =  p.PersonId
			LEFT  JOIN  County        AS  c  ON    a.county :: character varying  =  c.countyid :: character varying
			Left  Join  Alias  As  al  On  al.personid  =  p.personid
			WHERE (p.clientflag is null or p.clientflag in (1,2) or p.cisclientid is not null)
			AND CASE WHEN personid_list IS NOT NULL THEN p.personid != ANY (personid_list::uuid[]) ELSE TRUE END
			AND CASE WHEN v_lvFirstName  is NOT NULL THEN soundex_firstname = soundex(lower(trim(al.FirstName)))  ELSE TRUE END
			AND CASE WHEN v_lvLastName 	 is NOT NULL THEN soundex_lastname = soundex(lower(trim(al.LastName)))	 ELSE TRUE END
			AND CASE WHEN v_lvMiddleName is NOT NULL THEN soundex_middlename = soundex(lower(trim(al.MiddleName))) ELSE TRUE END
			AND CASE WHEN v_lvRace is NOT NULL THEN (p.RaceTypeKey = v_lvRace) ELSE TRUE END
			AND CASE WHEN v_lvGender is NOT NULL THEN (p.GenderTypeKey = v_lvGender) ELSE TRUE END
			AND CASE WHEN v_lDCNType is NOT NULL THEN (i.PersonIdentifierTypeKey = v_lDCNType) ELSE TRUE END
			AND CASE WHEN v_liDangerous is NOT NULL THEN (p.DangerLevel = v_liDangerous) ELSE TRUE END
			AND CASE WHEN v_liRegion is NOT NULL THEN (c.APSRegion = v_liRegion) ELSE TRUE END
			AND (CASE WHEN (v_lDLType is NOT NULL AND v_lDLValue is NOT NULL)
						THEN (i.PersonIdentifierTypeKey = v_lDLType AND i.PersonIdentifierValue ILIKE v_lDLValue)
					ELSE TRUE END)
			and CASE WHEN v_lvStateId is NOT NULL THEN a.state ILIKE v_lvStateId ELSE TRUE end
			AND  CASE  WHEN  v_lvAddress  is  NOT  NULL  THEN  (lower(a.address)  ILIKE  lower(v_lvAddress)||'%' )  ELSE  TRUE  end
			AND  CASE  WHEN  v_lvAddress2  is  NOT  NULL  THEN  (lower(a.address2) ILIKE  lower(v_lvAddress2)||'%' )  ELSE  TRUE  END
			AND CASE WHEN v_lvSocialMediaSrc is NOT NULL THEN (lower(p.socialmediasource) = lower(v_lvSocialMediaSrc)) ELSE TRUE END
			AND CASE WHEN v_lvFein is NOT NULL THEN (p.fein = v_lvFein) ELSE TRUE END
			AND CASE WHEN v_lvComplaintnumber is NOT NULL THEN (p.complaintnumber = v_lvComplaintnumber) ELSE TRUE end
			AND CASE WHEN v_lvcjamspid is NOT NULL THEN ( p.cjamspid = v_lvcjamspid::bigint) ELSE TRUE END
			AND CASE WHEN v_lvPetitionid is NOT NULL THEN (p.petitionid = v_lvPetitionid) ELSE TRUE END
			AND 
				CASE 
					WHEN v_lvAlias is NOT NULL 
					THEN ((concat(trim(lower(al.firstname)), case when al.lastname is not null then '' else ' '|| trim(lower(al.lastname)) end ) = v_alias_clean) and al.akatypetypekey='AN' and al.activeflag=1)
					ELSE true
				END
			AND CASE 
					WHEN v_lvMaidenName is NOT NULL 
					THEN ((concat(lower(al.firstname), case when al.lastname is not null then '' else ' '|| lower(al.lastname) end ) = v_maidenname_clean) and al.akatypetypekey='MN' and al.activeflag=1)
					ELSE true
				END
			AND CASE WHEN v_lvZip is NOT NULL THEN (lower(a.zipcode) = lower(v_lvZip)) ELSE TRUE END
			AND CASE WHEN v_lvState is NOT NULL THEN (a.state ILIKE v_lvState) ELSE TRUE END
			AND CASE WHEN v_lvCounty is NOT NULL THEN (a.county ILIKE v_lvCounty) ELSE TRUE END
			AND CASE WHEN v_lvCity is NOT NULL THEN (lower(a.city) = lower(v_lvCity)) ELSE TRUE END
			AND CASE WHEN v_lDCNValue is NOT NULL THEN (i.PersonIdentifierValue ILIKE v_lDCNValue) ELSE TRUE END
			AND CASE WHEN v_lvPhone is NOT NULL THEN (pn.phoneNumber ILIKE v_lvPhone) ELSE TRUE END
			AND CASE WHEN v_lvEmail is NOT NULL THEN (pe.email ILIKE v_lvEmail) ELSE TRUE END
			AND CASE WHEN v_lvOccupation is NOT NULL THEN (p.occupation ILIKE v_lvOccupation) ELSE TRUE END
			AND (v_liAge IS NULL OR date_part('year', age(now(), p.DOB)) = v_liAge)
			AND CASE WHEN v_lmdmType is NOT NULL THEN (i.PersonIdentifierTypeKey = v_lmdmType) ELSE TRUE end
			AND CASE WHEN v_lmdmValue is NOT NULL THEN (i.PersonIdentifierValue ilike '%'  || v_lmdmValue ||  '%' ) ELSE TRUE END
			AND CASE WHEN v_ldDOB is NOT NULL THEN (p.DOB BETWEEN v_dob_from AND v_dob_to) ELSE TRUE END 
			AND p.ActiveFlag  =  1;
			
		ELSE
			
			INSERT INTO KeyResults
			(PersonId, RankNo, MatchScore,NameRank, AliasRank)
			SELECT 
				distinct
				p.PersonId,
				0 AS match_rank,
				CASE 	WHEN v_lvFirstName is not null and coalesce(v_firstname_clean,' ') = trim(lower(p.FirstName)) THEN 1 
						WHEN v_lvFirstName is not null and coalesce(v_firstname_clean,' ') = trim(lower(al.FirstName)) THEN 1 
						WHEN v_lvFirstName is not null and trim(lower(p.FirstName)) like v_firstname_clean||'%' THEN 1 
						WHEN v_lvFirstName is not null and trim(lower(al.FirstName)) like v_firstname_clean||'%' THEN 1 
						WHEN v_lvFirstName is not null and coalesce(v_firstname_clean,' ') = split_part(trim(lower(p.FirstName)), ' ',1) THEN 1 
						WHEN v_lvFirstName is not null and coalesce(v_firstname_clean,' ') = split_part(trim(lower(al.FirstName)), ' ',1) THEN 1 
						ELSE 0 end
				+ CASE 	WHEN v_lvLastName is not null and coalesce(v_lastname_clean,' ') = trim(lower(p.LastName)) THEN 1 
						WHEN v_lvLastName is not null and coalesce(v_lastname_clean,' ') = trim(lower(al.LastName)) THEN 1 
						WHEN v_lvLastName is not null and trim(lower(p.LastName)) like v_lastname_clean||'%' THEN 1
						WHEN v_lvLastName is not null and trim(lower(al.LastName)) like v_lastname_clean||'%' THEN 1
						WHEN v_lvLastName is not null and coalesce(v_lastname_clean,' ') = split_part(trim(lower(p.LastName)), ' ',1) THEN 1 
						WHEN v_lvLastName is not null and coalesce(v_lastname_clean,' ') = split_part(trim(lower(al.LastName)), ' ',1) THEN 1 
						ELSE 0 end
				+ CASE WHEN v_lvMiddleName is not null and coalesce(v_middlename_clean,' ') = trim(lower(p.MiddleName)) THEN 1 
				WHEN v_lvMiddleName is not null and coalesce(v_middlename_clean,' ') = split_part(trim(lower(p.MiddleName)), ' ',2) THEN 1 ELSE 0 end
				::int as match_score,
				CASE 	WHEN v_lvFirstName is not null THEN COALESCE(difference(v_firstname_clean, trim(lower(p.FirstName))),0) ELSE 0 end
				+ CASE 	WHEN v_lvLastName is not null THEN COALESCE(difference(v_lastname_clean, trim(lower(p.LastName))),0) ELSE 0 end
				+ CASE 	WHEN v_lvMiddleName is not null THEN COALESCE(difference(v_middlename_clean, trim(lower(p.MiddleName))),0) ELSE 0 end
				::int as name_rank,
				CASE 	WHEN v_lvFirstName is not null THEN COALESCE(difference(v_firstname_clean, trim(lower(al.FirstName))),0) ELSE 0 end
				+ CASE 	WHEN v_lvLastName is not null THEN COALESCE(difference(v_lastname_clean, trim(lower(al.LastName))),0) ELSE 0 end
				+ CASE 	WHEN v_lvMiddleName is not null THEN COALESCE(difference(v_middlename_clean, trim(lower(al.MiddleName))),0) ELSE 0 end
				::int as alias_rank
			FROM    Person  AS  p  
			LEFT  JOIN  PersonIdentifier  AS  i  ON  i.PersonId  =  p.PersonId 
			LEFT  JOIN  PersonAddress    AS  a  ON  a.PersonId  =  p.PersonId  and  a.ActiveFlag  =  1  --AND  a.PersonAddressTypeKey  =  'C'
			LEFT  JOIN  PersonPhoneNumber  AS  pn  ON  pn.PersonId  =  p.PersonId
			LEFT  JOIN  PersonEmail  AS  pe  ON  pe.PersonId  =  p.PersonId
			LEFT  JOIN  County        AS  c  ON    a.county :: character varying  =  c.countyid :: character varying
			Left  Join  Alias  As  al  On  al.personid  =  p.personid
			WHERE (p.clientflag is null or p.clientflag in (1,2) or p.cisclientid is not null)
			AND CASE WHEN personid_list IS NOT NULL THEN p.personid != ANY (personid_list::uuid[]) ELSE TRUE END
			AND CASE WHEN v_lvRace is NOT NULL THEN (p.RaceTypeKey = v_lvRace) ELSE TRUE END
			AND CASE WHEN v_lvGender is NOT NULL THEN (p.GenderTypeKey = v_lvGender) ELSE TRUE END
			AND CASE WHEN v_lDCNType is NOT NULL THEN (i.PersonIdentifierTypeKey = v_lDCNType) ELSE TRUE END
			AND CASE WHEN v_liDangerous is NOT NULL THEN (p.DangerLevel = v_liDangerous) ELSE TRUE END
			AND CASE WHEN v_liRegion is NOT NULL THEN (c.APSRegion = v_liRegion) ELSE TRUE END
			AND (CASE WHEN (v_lDLType is NOT NULL AND v_lDLValue is NOT NULL)
						THEN (i.PersonIdentifierTypeKey = v_lDLType AND i.PersonIdentifierValue ILIKE v_lDLValue)
					ELSE TRUE END)
			and CASE WHEN v_lvStateId is NOT NULL THEN a.state ILIKE v_lvStateId ELSE TRUE end
			AND CASE WHEN  v_lvAddress  is  NOT  NULL  THEN  (lower(a.address)  ILIKE  lower(v_lvAddress)||'%' )  ELSE  TRUE  end
			AND CASE WHEN  v_lvAddress2  is  NOT  NULL  THEN  (lower(a.address2) ILIKE  lower(v_lvAddress2)||'%' )  ELSE  TRUE  END
			AND CASE WHEN v_lvSocialMediaSrc is NOT NULL THEN (lower(p.socialmediasource) = lower(v_lvSocialMediaSrc)) ELSE TRUE END
			AND CASE WHEN v_lvFein is NOT NULL THEN (p.fein = v_lvFein) ELSE TRUE END
			AND CASE WHEN v_lvComplaintnumber is NOT NULL THEN (p.complaintnumber = v_lvComplaintnumber) ELSE TRUE end
			AND CASE WHEN v_lvcjamspid is NOT NULL THEN ( p.cjamspid = v_lvcjamspid::bigint) ELSE TRUE END
			AND CASE WHEN v_lvPetitionid is NOT NULL THEN (p.petitionid = v_lvPetitionid) ELSE TRUE END
			AND 
				CASE 
					WHEN v_lvAlias is NOT NULL 
					THEN ((concat(trim(lower(al.firstname)), case when al.lastname is not null then '' else ' '|| trim(lower(al.lastname)) end ) = v_alias_clean) and al.akatypetypekey='AN' and al.activeflag=1)
					ELSE true
				END
			AND CASE 
					WHEN v_lvMaidenName is NOT NULL 
					THEN ((concat(lower(al.firstname), case when al.lastname is not null then '' else ' '|| lower(al.lastname) end ) = v_maidenname_clean) and al.akatypetypekey='MN' and al.activeflag=1)
					ELSE true
				END
			AND CASE WHEN v_lvZip is NOT NULL THEN (lower(a.zipcode) = lower(v_lvZip)) ELSE TRUE END
			AND CASE WHEN v_lvState is NOT NULL THEN (a.state ILIKE v_lvState) ELSE TRUE END
			AND CASE WHEN v_lvCounty is NOT NULL THEN (a.county ILIKE v_lvCounty) ELSE TRUE END
			AND CASE WHEN v_lvCity is NOT NULL THEN (lower(a.city) = lower(v_lvCity)) ELSE TRUE END
			AND CASE WHEN v_lDCNValue is NOT NULL THEN (i.PersonIdentifierValue ILIKE v_lDCNValue) ELSE TRUE END
			AND CASE WHEN v_lvPhone is NOT NULL THEN (pn.phoneNumber ILIKE v_lvPhone) ELSE TRUE END
			AND CASE WHEN v_lvEmail is NOT NULL THEN (pe.email ILIKE v_lvEmail) ELSE TRUE END
			AND CASE WHEN v_lvOccupation is NOT NULL THEN (p.occupation ILIKE v_lvOccupation) ELSE TRUE END
			AND (v_liAge IS NULL OR date_part('year', age(now(), p.DOB)) = v_liAge)
			AND CASE WHEN v_lmdmType is NOT NULL THEN (i.PersonIdentifierTypeKey = v_lmdmType) ELSE TRUE end
			AND CASE WHEN v_lmdmValue is NOT NULL THEN (i.PersonIdentifierValue ilike '%'  || v_lmdmValue ||  '%' ) ELSE TRUE END
			AND CASE WHEN v_ldDOB is NOT NULL THEN (p.DOB BETWEEN v_dob_from AND v_dob_to) ELSE TRUE END 
			AND p.ActiveFlag  =  1;
		
		END IF;

	END IF;
		
SELECT COUNT(1) INTO v_krcount FROM KeyResults;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
	
RAISE NOTICE 'v_krcount::  %', v_krcount;

RAISE NOTICE 'v_lvStateId  Count-->%', v_lvStateId;

UPDATE  KeyResults  as  KR  SET  PersonAddressId    =  (SELECT    PRA.PersonAddressId                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                                                          FROM  PersonAddress  PRA                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                                                         WHERE  PRA.PersonId  =  KR.PersonId                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
                                                         --AND  PRA.PersonAddressTypeKey  =  'C'                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
                                                         AND  CASE  WHEN  v_lvAddress  is  NOT  NULL  THEN  (PRA.address  ILIKE  LEFT(v_lvAddress,  5)  ||  '%')  ELSE  TRUE  end
                                                         AND  CASE  WHEN  v_lvAddress2  is  NOT  NULL  THEN  (PRA.address2  ILIKE  LEFT(v_lvAddress2,  5)  ||  '%')  ELSE  TRUE  END
                                                         AND  CASE  WHEN  v_lvZip  is  NOT  NULL  THEN  (PRA.zipcode  ILIKE  LEFT(v_lvZip,  4)  ||  '%')  ELSE  TRUE  END                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                                                         AND  CASE  WHEN  v_lvState  is  NOT  NULL  THEN  (PRA.state  ILIKE  v_lvState  ||  '%')  ELSE  TRUE  END                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                                                         AND  CASE  WHEN  v_lvCounty  is  NOT  NULL  THEN  (PRA.county  ILIKE  LEFT(v_lvCounty,  3)    ||  '%')  ELSE  TRUE  END                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
                                                         AND  PRA.ActiveFlag  =  1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                         ORDER  BY  PRA.insertedon  DESC    LIMIT  1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                                                         );                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   

         
	CREATE TEMP TABLE ReturnResults (       
		totalcount bigint,
		exactmatch boolean,
		rankno int,
		source character varying,
		personid uuid,
		personroleid uuid,
		personaddressid uuid,
		personroletype character varying,
		personrolesubtype character varying,
		firstname character varying,
		middlename character varying,
		lastname character varying,
		dob timestamp without time zone,
		dangerlevel integer,
		dateofdeath timestamp without time zone,
		isapproxdod integer,
		suffix character varying,
		prefx character varying,
		deceased bit,
		socialmediasource character varying,
		userphoto text,
		ssn character varying,
		mdm_id character varying,
		dcn character varying,
		dl character varying,
		primaryaddress character varying,
		address varchar(100), address2 varchar(100), county varchar(50), city varchar(50), state varchar(2), zipcode varchar(50),
		homephone character varying,
		gendertypekey character varying,
		loadnumber character varying,
		teamname character varying,
		priors bigint,
		relationscount bigint,
		relations text,
		alias text,
		assistpid character varying,
		cjamspid character varying,
		primarylanguageid character varying,
		secondarylanguageid character varying,
		primarylanguage character varying,
		secondarylanguage character varying,
		safehavenbabyflag integer,
		racetypekey text,
		ethnicgrouptypekey character varying,
		cisclientid character varying,
		isbioadoptedflag integer,
		isProvider character varying
	);

insert into ReturnResults (
		totalcount,
		exactmatch,
		rankno,
		source,
		personid,
		personroleid,
		personaddressid,
		personroletype,
		personrolesubtype,
		firstname,
		middlename,
		lastname,
		dob,
		dangerlevel,
		dateofdeath,
		isapproxdod,
		suffix,
		prefx,
		deceased,
		socialmediasource,
		userphoto,
		ssn,
		mdm_id,
		dcn,
		dl,
		primaryaddress,
		address,
		address2,
		county,
		city,
		state,
		zipcode,
		homephone,
		gendertypekey,
		loadnumber,
		teamname,
		priors,
		relationscount,
		relations,
		alias,
		assistpid,
		cjamspid,
		primarylanguageid,
		secondarylanguageid,
		primarylanguage,
		secondarylanguage,
		safehavenbabyflag,
		racetypekey,
		ethnicgrouptypekey,
		cisclientid,
		isbioadoptedflag,
		isProvider
		)
 SELECT count(1)over(),
		case when searchargperson > 0 and FR.MatchScore <> searchargperson then false else true end as exactmatch,
      FR.Rankno, 
      'Local'::character  varying,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
      FR.PersonId,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
      CAST('00000000-0000-0000-0000-000000000000'  as  uuid  )  AS  PersonRoleId,
      FR.personaddressid,
      CAST  ('None'  as  character  varying)    AS  PersonRoleType,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
      (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
          SELECT  string_agg(distinct AC.ActorType,  ',')                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
          FROM  Actor  AC                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
          WHERE  AC.PersonId  =  FR.PersonId                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
      ) AS PersonRoleSubType,
      case when FR.NameRank >= FR.AliasRank THEN p.FirstName else 
		(Select al.firstname FROM  Alias  al                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
				WHERE  al.personid  =  FR.personid
				and al.activeflag=1 
				and CASE WHEN v_lvFirstName is NOT NULL THEN soundex_firstname = soundex(trim(lower(al.FirstName)))
				ELSE TRUE END
			    limit 1) 
	  end,
	  case when FR.NameRank >= FR.AliasRank THEN p.MiddleName else 
		(Select al.firstname FROM  Alias  al                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
				WHERE  al.personid  =  FR.personid
				and al.activeflag=1 
				and CASE WHEN v_lvMiddleName is NOT NULL THEN soundex_middlename = soundex(trim(lower(al.MiddleName)))
				ELSE TRUE END
			    limit 1) 
	  end,
	  case when FR.NameRank >= FR.AliasRank THEN p.LastName else 
		(Select al.lastname FROM  Alias  al                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
				WHERE  al.personid  =  FR.personid
				and al.activeflag=1 
				and CASE WHEN v_lvLastName is NOT NULL THEN soundex_lastname = soundex(trim(lower(al.LastName)))
				ELSE TRUE END
			    limit 1) 
	  end,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
      p.DOB,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
      p.DangerLevel,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
      p.dateofdeath,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
      p.isapproxdod,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
      p.suffix,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
      p.prefx,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
      p.deceased,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
      p.socialmediasource,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
      p.userphoto,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
     (SELECT  i.PersonIdentifierValue                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
       FROM  PersonIdentifier  AS  i                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
       WHERE  i.PersonId  =  FR.PersonId                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
         AND  i.ActiveFlag  =  1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
         AND  i.PersonIdentifierTypeKey  =  'SSN'  limit  1)  AS  SSN, 
           
     (SELECT  i.PersonIdentifierValue                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
       FROM  PersonIdentifier  AS  i                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
       WHERE  i.PersonId  =  FR.PersonId                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
         AND  i.ActiveFlag  =  1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
         AND  i.PersonIdentifierTypeKey  =  'MDM_ID'  limit  1)  AS mdm_id ,  
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
     (SELECT  j.PersonIdentifierValue                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
       FROM  PersonIdentifier  AS  j                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
       WHERE  j.PersonId  =  FR.PersonId                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
         AND  j.ActiveFlag  =  1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
         AND  j.PersonIdentifierTypeKey  =  'DCN'  limit  1)  AS  DCN,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
                                                                            
     (SELECT  j.PersonIdentifierValue                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
       FROM  PersonIdentifier  AS  j                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
       WHERE  j.PersonId  =  FR.PersonId                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
         AND  j.ActiveFlag  =  1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
         AND  j.PersonIdentifierTypeKey  =  'DL'  limit  1)  AS  DL,     
	CAST(substring(COALESCE(TRIM(person_address.address),''),1,20)||'~'||  substring(COALESCE(TRIM(person_address.address2),''),1,20)  ||'~'||  COALESCE(TRIM(person_address.city),'')  ||'~'||  COALESCE(TRIM(person_address.zipcode),'')||'~'||  COALESCE(TRIM(person_address.county),'')  ||'~'||  COALESCE(person_address.state,'')as  character  varying) as primaryaddress,
     person_address.address,
     person_address.address2,
     person_address.county,
     person_address.city,
     person_address.state,
     person_address.zipcode,
     (SELECT  PP.phoneNumber                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
       FROM  PersonPhoneNumber  AS  PP                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
       WHERE  PP.PersonId  =  FR.PersonId                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
         AND  PP.PersonPhoneTypeKey  =  'H'  limit  1)  AS  HomePhone,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
      p.GenderTypeKey,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
      null as LoadNumber,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
      null as TeamName,
     (select sum (x) as Priors from  
      (((SELECT  COALESCE(COUNT(1),0)  as x                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
       FROM  IntakeServiceRequest  ISR                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
       join  IntakeSerReqStatusType  ISRST  ON  ISR.IntakeSerReqStatusTypeId  =  ISRST.IntakeSerReqStatusTypeId                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
       Left  join    ServiceRequestSubType  SRST  ON  SRST.ServiceRequestSubTypeId  =  ISR.IntakeServiceRequestClassId                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
       JOIN  IntakeServiceRequestActor  ISRA  ON  ISR.IntakeServiceId  =  ISRA.IntakeServiceId                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
       JOIN  Actor  AC  ON  AC.ActorId  =  ISRA.ActorId                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
       AND  AC.ActiveFlag  =  1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
       JOIN  Person  PR  ON  PR.PersonId  =  AC.PersonId
       WHERE  ISR.ActiveFlag  =  1 
       and  (select count(1) from intakeservicerequestactor insa where insa.intakeservicerequestactorid= ISRA.intakeservicerequestactorid and insa.spexpungementflag =1) = 0
       AND  PR.PersonId  =  FR.PersonId    )
      union all
  ( SELECT  COALESCE(COUNT(1),0) as x  
      from adoptioncase ac 
	   left join adoptioncaseactor acar on ac.adoptioncaseid = acar.adoptioncaseid
   	   left join adoptioncasedisposition acd on acd.adoptioncaseid = ac.adoptioncaseid
		where acar.personid = FR.PersonId)))as x)   ,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
   case when (select count(*) from personrelation)>1 then (SELECT  COALESCE(COUNT(1),0)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
       FROM  PersonRelation  PerRel                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
       WHERE  PerRel.ActiveFlag  =  1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
         AND  PerRel.PersonId  =  FR.PersonId) else null end AS  RelationsCount,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
     (select json_agg(v)
       from (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
             SELECT  
               PR.firstname  ||  '  '  ||  PR.lastname as personname,
               PRT.description  as  relationtype,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
               CASE 
                 WHEN PerRel.relationcategory = 'P' THEN 'Primary'                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                 WHEN PerRel.relationcategory = 'S' THEN 'Secondary'                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                 WHEN PerRel.relationcategory = 'O' THEN 'Other'                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
               END AS relationcategory                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
             FROM  PersonRelation  PerRel
             JOIN  Person  PR  ON  PR.PersonId  =  PerRel.PersonRelativeId
             Join  relationshiptype  PRT  On  PRT.relationshiptypekey  =  PerRel.actorrelationshipkey and prt.activeflag = 1
             WHERE  PR.ActiveFlag  =  1  AND  PerRel.ActiveFlag  =  1
             AND  PerRel.PersonId  =  FR.PersonId                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
       ) as v
     )  AS  Relations,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
     (Select  
       al.firstname  ||  '  '  || ( case when al.lastname is not null then al.lastname else '' end ) 
       FROM  Alias  al                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
       WHERE  al.personid  =  FR.personid
         and al.activeflag=1
         and CASE  WHEN  v_lvAlias  is  NOT  NULL  THEN  (trim(lower(al.firstname))  ilike  left(lower(v_lvAlias),  3) ||  '%' or trim(lower(al.lastname))   ilike  left(lower(v_lvAlias),  12)  ||  '%')  ELSE  TRUE  END  
	         limit 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
     ) AS  Alias,
      p.fk_id as assistpid,
      p.cjamspid,
      p.primarylanguageid,
      p.secondarylanguageid,
      rv.description as primarylanguage,
      rvs.description as secondarylanguage,
      p.safehavenbabyflag,
     (select json_agg(v)
       from     
       (Select  
       rv.value_text
       FROM  personracetypemap  prtm join referencevalues rv on  rv.ref_key = prtm.racetypekey and rv.referencetypeid = 171 and rv.activeflag = 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
       WHERE  prtm.personid  =  p.personid
         and prtm.activeflag=1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
     )as v
     ) AS  racetypekey,
      p.ethnicgrouptypekey,
	  coalesce((select pii.personidentifiervalue from personidentifier pii where pii.personidentifiertypekey = 'IRN' and pii.personid = p.personid and pii.activeflag = 1 limit 1), p.cisclientid) as assistpid,
	  p.isbioadoptedflag,
	  (case when p.providerid is not null and p.providerid != 0 then 'Yes' else '' end) 
    FROM  KeyResults AS FR
    JOIN  Person AS p ON p.PersonId = FR.PersonId                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
    left JOIN referencevalues as rv  ON p.primarylanguageid=rv.ref_key                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
    left JOIN referencevalues AS rvs ON p.secondarylanguageid=rvs.ref_key
 -- below change done for fetching county name from county table
    left join lateral (
       SELECT  PA.address, PA.address2,  
       PA.city, PA.state, PA.zipcode,
       (select CC.countyname from  County cc where  cc.countyid :: character varying = PA.county :: character varying )  as county 
       FROM  PersonAddress  AS  PA           
       WHERE  PA.PersonId  =  FR.PersonId                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
         AND  PA.PersonAddressId  =  FR.PersonAddressId  limit  1) person_address on true
		LIMIT v_liPageSize OFFSET v_pageoffset ; 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
  SELECT  COUNT(distinct RR.*)  INTO  v_liCount                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
  FROM  ReturnResults RR;
  
  UPDATE ReturnResults
  SET totalcount = v_liCount;
 
  IF  v_liCount  IS  NULL  THEN
    v_liCount  :=  0;
  END  IF;
  IF  COALESCE(v_liPageNumber,  0)  <  1  THEN
    v_liPageNumber  :=  1;
  END  IF;
  IF  COALESCE(v_liPageSize,  0)  <  1  THEN
    v_liPageSize  :=  v_liCount;
  END  IF;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
  RAISE  NOTICE  '33333-->>%',v_liPageSize;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
  RAISE  NOTICE  '33333-->>>>>%',v_pageoffset;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
  RAISE  NOTICE  'mmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmmm-->%',now();                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
  RAISE  NOTICE  'Sorted  Results  Count-->%',cnt;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
 
  RETURN  QUERY EXECUTE 'Select distinct totalcount,
		exactmatch,
		rankno,
		source,
		personid,
		personroleid,
		personroletype,
		personrolesubtype,
		firstname,
		middlename,
		lastname,
		dob,
		dangerlevel,
		dateofdeath,
		isapproxdod,
		suffix,
		prefx,
		deceased,
		socialmediasource,
		userphoto,
		ssn,
		mdm_id,
		dcn,
		dl,
		primaryaddress,
		address,
     	address2,
	    county,
	    city,
	    state,
	    zipcode,
		homephone,
		gendertypekey,
		loadnumber,
		teamname,
		priors,
		relationscount,
		relations,
		alias,
		assistpid,
		cjamspid,
		primarylanguageid,
		secondarylanguageid,
		primarylanguage,
		secondarylanguage,
		safehavenbabyflag,
		racetypekey,
		ethnicgrouptypekey, 
		cisclientid ,
        isbioadoptedflag, 
		isProvider FROM  ReturnResults sr LIMIT ' || v_liPageSize || ' OFFSET ' ||  v_pageoffset ;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
  RAISE  NOTICE  'nnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnn-->%',now();
 
  DROP TABLE  sp_temp_searchParms;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
  DROP TABLE sp_temp_PersonIdentityTypes;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
  DROP TABLE sp_temp_PersonIdentityValues;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
  DROP TABLE KeyResults;   
  DROP TABLE ReturnResults; 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
 END;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
 $function$
;
 